import{_ as s,l as i,o as e,c as d,v as r,p as n,x as o,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"寻址方式","description":"","frontmatter":{"title":"寻址方式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/addressing-modes.md","filePath":"cs/addressing-modes.md","lastUpdated":1789023840000}'),E={name:"cs/addressing-modes.md"};function h(m,a,C,B,A,_){const t=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=r('<h1 id="寻址方式" tabindex="-1">寻址方式 <a class="header-anchor" href="#寻址方式" aria-label="Permalink to &quot;寻址方式&quot;">​</a></h1><div class="epigraph"><p>操作数可以在寄存器里、在指令的立即数里，或在「基址加偏移」指出的内存里；方式越多，译码与数据通路上的 MUX 越多。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/instruction-format">指令格式</a>钉死了 RISC-V 的 R/I/S/B/U/J 字段。本课不重拼立即数位，也不从 x86 的 SIB 字节另起一张总表。缺口是字段对应的<strong>操作数从哪来</strong>：后课 RISC 与 CISC 的分野，很大程度是寻址方式多寡。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>寄存器寻址：操作数是 <code>x[rs]</code>。立即：指令里的常数（已符号扩展）。PC 相对：分支/JAL 的目标。基址+偏移：<code>lw</code>/<code>sw</code> 的 <code>x[rs1]+imm</code>。缺口不是再切 opcode，而是这几种如何接到 ALUSrc、访存地址口。RISC-V 整数核几乎只有这些；没有存储器间接、没有带比例因子的双寄存器寻址。</p><p>CISC 常见「一个操作数在内存、带变址」。本课只列对照，不把 x86 模式表抄完——那是下一课的动机。</p><h3 id="寻址方式不是「虚拟内存页表」" tabindex="-1">寻址方式不是「虚拟内存页表」 <a class="header-anchor" href="#寻址方式不是「虚拟内存页表」" aria-label="Permalink to &quot;寻址方式不是「虚拟内存页表」&quot;">​</a></h3><p>这里的地址是指令算出的有效地址，还没有页表、没有 MMU。<a href="/cs/positional-notation">进制</a>的字节编址已经够用。把 addressing modes 理解成 OS 的 mmap，会跳过组成。</p><p><span class="marginnote">Patterson/Hennessy 强调 RISC-V 的简单寻址以保持单周期可画。Harris 在数字设计侧把立即数与寄存器当 MUX 输入。本课不讲 PIC 的 GOT。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 RV32I：R 型两寄存器；I 型寄存器+imm（含 <code>lw</code> 地址、<code>addi</code>）；S 型两寄存器+imm 写存；B/J 的 imm 加 PC。译码只选 ALU 输入与是否访存，不先跑复杂地址状态机。</p>',11)),(e(),n(p,null,{default:o(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FMT%5B%22%E6%A0%BC%E5%BC%8F%E5%AD%97%E6%AE%B5%22%5D%20--%3E%20REG%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E6%93%8D%E4%BD%9C%E6%95%B0%22%5D%0A%20%20FMT%20--%3E%20IMM%5B%22%E7%AB%8B%E5%8D%B3%20%2F%20PC%20%E7%9B%B8%E5%AF%B9%22%5D%0A%20%20FMT%20--%3E%20BASE%5B%22%E5%9F%BA%E5%9D%80%E5%8A%A0%E5%81%8F%E7%A7%BB%E8%AE%BF%E5%AD%98%22%5D%0A%20%20BASE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ARISC%20%E4%B8%BA%E4%BD%95%E5%B0%91%E6%96%B9%E5%BC%8F%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>简单寻址让有效地址在一级加法器内算完，塞进<a href="/cs/critical-path">关键路径</a>。方式一多，就要微码或多拍地址计算——CISC 的组成代价。<code>x0</code> 作基址给出绝对地址（零页），仍是基址+偏移，不是新方式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲向量散射/聚集、不把段寄存器请进来。间接跳转 <code>jalr</code> 是寄存器里的目标，仍属寄存器寻址的 PC 更新。</p><p>后课默认：RV32I 寻址是寄存器、立即、基址+偏移、PC 相对。下一课用「方式多少」对照 RISC/CISC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>操作数来源决定数据通路 MUX，不是页表。</li><li>RISC-V 故意只留很少几种寻址。</li><li>有效地址一级加即可，为单周期铺路。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；Harris and Harris。</li></ul>',7))])}const f=s(E,[["render",h]]);export{u as __pageData,f as default};
